PRAGMA foreign_keys = ON;
CREATE TABLE profiles (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','STAFF_SIDOARJO','STAFF_MERAUKE')), is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE sessions (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, profile_id TEXT NOT NULL REFERENCES profiles(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE business_counters (scope TEXT PRIMARY KEY, last_value INTEGER NOT NULL DEFAULT 0 CHECK(last_value>=0), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE login_rate_limits (identifier_hash TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, window_started_at TEXT NOT NULL, blocked_until TEXT);
CREATE TABLE customers (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, normalized_name TEXT, phone TEXT, address TEXT, notes TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE rate_configs (id TEXT PRIMARY KEY, name TEXT NOT NULL, rate_per_kg_idr INTEGER, minimum_charge_idr INTEGER, volumetric_divisor REAL, rounding_step_kg REAL, valid_from TEXT, valid_until TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), notes TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE packages (id TEXT PRIMARY KEY, package_code TEXT NOT NULL UNIQUE, customer_id TEXT REFERENCES customers(id), tracking_number TEXT NOT NULL, normalized_tracking_number TEXT NOT NULL, courier TEXT, received_at TEXT NOT NULL, received_date TEXT NOT NULL, received_time TEXT, actual_weight_kg REAL, length_cm REAL, width_cm REAL, height_cm REAL, volumetric_weight_kg REAL, chargeable_weight_kg REAL, charge_type TEXT NOT NULL CHECK(charge_type IN ('WEIGHT','VOLUMETRIC','FIXED','MANUAL')), shipping_fee_idr INTEGER NOT NULL DEFAULT 0 CHECK(shipping_fee_idr>=0), rate_config_id TEXT REFERENCES rate_configs(id), pricing_snapshot TEXT, status TEXT NOT NULL DEFAULT 'WAITING_CLOSING' CHECK(status IN ('WAITING_CLOSING','READY_TO_SHIP','IN_TRANSIT','ARRIVED_MERAUKE','READY_FOR_PICKUP','COMPLETED','HOLD','DAMAGED','MISSING')), duplicate_override INTEGER NOT NULL DEFAULT 0 CHECK(duplicate_override IN (0,1)), duplicate_override_reason TEXT, storage_location TEXT, notes TEXT, created_by TEXT NOT NULL REFERENCES profiles(id), updated_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE package_attachments (id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES packages(id), type TEXT NOT NULL CHECK(type IN ('RECEIVED','ARRIVAL','DAMAGED','OTHER')), storage_path TEXT NOT NULL UNIQUE, original_filename TEXT, mime_type TEXT, size_bytes INTEGER, uploaded_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE closings (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, closing_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','FINALIZED','IN_SHIPMENT','ARRIVED','COMPLETED','CANCELLED')), notes TEXT, package_count INTEGER NOT NULL DEFAULT 0, total_actual_weight_kg REAL NOT NULL DEFAULT 0, total_chargeable_weight_kg REAL NOT NULL DEFAULT 0, total_amount_idr INTEGER NOT NULL DEFAULT 0, finalized_at TEXT, finalized_by TEXT REFERENCES profiles(id), cancellation_reason TEXT, created_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE closing_packages (id TEXT PRIMARY KEY, closing_id TEXT NOT NULL REFERENCES closings(id), package_id TEXT NOT NULL REFERENCES packages(id), actual_weight_snapshot_kg REAL, chargeable_weight_snapshot_kg REAL, shipping_fee_snapshot_idr INTEGER, customer_id_snapshot TEXT REFERENCES customers(id), is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), merauke_check_status TEXT NOT NULL DEFAULT 'PENDING' CHECK(merauke_check_status IN ('PENDING','OK','DAMAGED','MISSING')), merauke_checked_at TEXT, merauke_checked_by TEXT REFERENCES profiles(id), merauke_notes TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(closing_id,package_id));
CREATE TABLE shipments (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','READY','DEPARTED','ARRIVED','RECONCILED','COMPLETED','CANCELLED')), vessel_name TEXT, departure_at TEXT, estimated_arrival_at TEXT, actual_arrival_at TEXT, notes TEXT, created_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE shipment_closings (shipment_id TEXT NOT NULL REFERENCES shipments(id), closing_id TEXT NOT NULL UNIQUE REFERENCES closings(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(shipment_id,closing_id));
CREATE TABLE arrival_checks (id TEXT PRIMARY KEY, shipment_id TEXT NOT NULL REFERENCES shipments(id), package_id TEXT NOT NULL REFERENCES packages(id), condition TEXT NOT NULL CHECK(condition IN ('OK','DAMAGED')), checked_at TEXT NOT NULL, checked_by TEXT NOT NULL REFERENCES profiles(id), notes TEXT, UNIQUE(shipment_id,package_id));
CREATE TABLE invoices (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, closing_id TEXT NOT NULL REFERENCES closings(id), customer_id TEXT NOT NULL REFERENCES customers(id), status TEXT NOT NULL DEFAULT 'UNPAID' CHECK(status IN ('UNPAID','PARTIAL','PAID','VOID')), total_idr INTEGER NOT NULL, paid_idr INTEGER NOT NULL DEFAULT 0, balance_idr INTEGER NOT NULL, notes TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(closing_id,customer_id));
CREATE TABLE invoice_items (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), package_id TEXT NOT NULL REFERENCES packages(id), description TEXT, amount_idr INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(invoice_id,package_id));
CREATE TABLE payments (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), amount_idr INTEGER NOT NULL, method TEXT NOT NULL CHECK(method IN ('CASH','BANK_TRANSFER','OTHER')), paid_at TEXT NOT NULL, reference TEXT, notes TEXT, idempotency_key TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(created_by,idempotency_key));
CREATE TABLE expenses (id TEXT PRIMARY KEY, expense_date TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('SEA_FREIGHT','TRANSPORT','PACKAGING','SALARY','RENT','OPERATIONS','OTHER')), amount_idr INTEGER NOT NULL, closing_id TEXT REFERENCES closings(id), shipment_id TEXT REFERENCES shipments(id), description TEXT NOT NULL, notes TEXT, created_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE pickups (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), picked_up_at TEXT NOT NULL, recipient_name TEXT, notes TEXT, idempotency_key TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(created_by,idempotency_key));
CREATE TABLE pickup_packages (pickup_id TEXT NOT NULL REFERENCES pickups(id), package_id TEXT NOT NULL UNIQUE REFERENCES packages(id), PRIMARY KEY(pickup_id,package_id));
CREATE TABLE package_status_history (id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES packages(id), from_status TEXT, to_status TEXT NOT NULL, reason TEXT, actor_id TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES profiles(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, metadata TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE system_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_by TEXT REFERENCES profiles(id), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE UNIQUE INDEX closing_packages_one_active_package ON closing_packages(package_id) WHERE is_active=1;
CREATE INDEX packages_received_date_idx ON packages(received_date DESC,received_time DESC); CREATE INDEX packages_tracking_idx ON packages(normalized_tracking_number); CREATE INDEX customers_name_idx ON customers(name); CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TRIGGER profiles_updated_at AFTER UPDATE ON profiles WHEN NEW.updated_at=OLD.updated_at BEGIN UPDATE profiles SET updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE TRIGGER customers_updated_at AFTER UPDATE ON customers WHEN NEW.updated_at=OLD.updated_at BEGIN UPDATE customers SET updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE TRIGGER packages_updated_at AFTER UPDATE ON packages WHEN NEW.updated_at=OLD.updated_at BEGIN UPDATE packages SET updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
